//! Cargo-driven `itss.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x738e0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff05000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff05000000u64)),
        o => panic!("itss-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/win32/itss/itss_r.o", "engine:uuid", "engine:wine", "engine:c:wine_dll_register", "engine:oldnames", "import:urlmon", "import:shlwapi", "import:ole32", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "body"],
        "x86_64" => &["dll/win32/itss/itss_r.o", "engine:uuid", "engine:wine", "engine:c:wine_dll_register", "engine:oldnames", "import:urlmon", "import:shlwapi", "import:ole32", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "body"],
        "aarch64" => &["dll/win32/itss/itss_r.o", "engine:uuid", "engine:wine", "engine:c:wine_dll_register", "engine:oldnames", "import:urlmon", "import:shlwapi", "import:ole32", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "body"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/itss",
        "dll/win32/itss",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("itss_shims", &["dll/win32/itss/chm_lib.c", "dll/win32/itss/lzx.c", "dll/win32/itss/itss.c", "dll/win32/itss/moniker.c", "dll/win32/itss/protocol.c", "dll/win32/itss/storage.c", "dll/win32/itss/guid.c"])
        .rc("dll/win32/itss/rsrc.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/itss/itss.spec", "itss.dll")
        .spec_stubs()
        .import_lib("dll/win32/urlmon/urlmon.spec", "urlmon.dll", "urlmon")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
